import { Component } from '@angular/core';
import { ProdavnicaService } from '../prodavnica.service';
import jwt_decode from 'jwt-decode';
import { ArtikalService } from '../artikal.service';

@Component({
  selector: 'app-dodavanje-artikla',
  templateUrl: './dodavanje-artikla.component.html',
  styleUrls: ['./dodavanje-artikla.component.css']
})
export class DodavanjeArtiklaComponent {
  artikli: any[] = [];
  email: string = '';
  errors: string[] = [];
  successMessage: string | null = null;

  constructor(
    private prodavnicaService: ProdavnicaService,
    private artikalService: ArtikalService
  ) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.email = decodedToken.email;
    }
  }

  removeArtikal(index: number): void {
    this.artikli.splice(index, 1);
    this.errors.splice(index, 1);
  }

  onFileChange(event: any) {
    const files: FileList = event.target.files;
    this.artikli = [];
    this.errors = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const reader = new FileReader();

      reader.onload = (e: any) => {
        const index = this.artikli.length;

        this.artikli.push({
          file: file,
          preview: e.target.result,
          tip: '',
          kategorija: '',
          velicina: '',
          boja: '',
          cena: '',
          opis: '',
          aiLoading: true,
          aiError: ''
        });
        this.errors.push('');

        // Pozovi AI za ovaj artikal
        this.callAIForArtikal(index);
      };

      reader.readAsDataURL(file);
    }
  }

  // Poziv AI klasifikacije ka backendu
  callAIForArtikal(index: number) {
    const artikal = this.artikli[index];
    if (!artikal) return;

    this.artikalService.classifyArtikal(artikal.file).subscribe(
      (res) => {
        // očekujemo { tip, kategorija, boja }
        artikal.tip = res.tip;
        artikal.kategorija = res.kategorija;
        artikal.boja = res.boja;
        artikal.aiLoading = false;
        artikal.aiError = '';
      },
      (err) => {
        console.error('AI klasifikacija nije uspela', err);
        artikal.aiLoading = false;
        artikal.aiError = 'AI nije uspeo da prepozna artikal, popunite ručno.';
      }
    );
  }

  // Validacija: obavezno samo veličina i cena
  validateField(artikal: any, index: number) {
    if (!artikal.velicina || !artikal.cena) {
      this.errors[index] = 'Veličina i cena su obavezne.';
    } else {
      this.errors[index] = '';
    }
  }

  onSubmit() {
    let hasErrors = false;
    let savedCount = 0;

    this.artikli.forEach((artikal, index) => {
      if (!artikal.velicina || !artikal.cena) {
        this.errors[index] = 'Veličina i cena su obavezne.';
        hasErrors = true;
      } else {
        this.errors[index] = '';
      }
    });

    if (hasErrors) {
      return;
    }

    this.artikli.forEach((artikal, index) => {
      const formData = new FormData();
      formData.append('image', artikal.file);
      formData.append('tip', artikal.tip || 'Nepoznato');
      formData.append('kategorija', artikal.kategorija || 'Nepoznato');
      formData.append('velicina', artikal.velicina);
      formData.append('boja', artikal.boja || 'Nepoznata');
      formData.append('cena', artikal.cena);
      formData.append('opis', artikal.opis || '');
      formData.append('email', this.email);

      this.artikalService.saveArtikal(formData).subscribe(
        () => {
          savedCount++;
          if (savedCount === this.artikli.length) {
            this.successMessage = 'Svi artikli su uspešno sačuvani!';
            this.artikli = [];
            setTimeout(() => (this.successMessage = null), 5000);
          }
        },
        (error) => {
          console.error(`Greška pri čuvanju artikla ${index + 1}.`, error);
        }
      );
    });
  }
}
<div class="form-container">
  <h1>Dodajte Artikal</h1>

  <!-- Poruka o uspešnom dodavanju -->
  <div *ngIf="successMessage" class="success-message">
    {{ successMessage }}
  </div>

  <div class="form-group">
    <label for="images">Izaberite slike:</label>
    <div class="custom-file-upload">
      <input
        type="file"
        id="images"
        (change)="onFileChange($event)"
        accept="image/*"
        multiple
      />
    </div>
  </div>

  <div *ngIf="artikli.length > 0" class="artikli-container">
    <div *ngFor="let artikal of artikli; let i = index" class="artikal-form">
      <span class="remove-icon" (click)="removeArtikal(i)">✖</span>

      <!-- Preview slike -->
      <img [src]="artikal.preview" alt="Artikal slika" class="artikal-image" />

      <div class="artikal-details">
        <!-- Tip (automatski popunjen, može ručno da se promeni) -->
        <label for="tip-{{ i }}">Tip:</label>
        <select
          id="tip-{{ i }}"
          [(ngModel)]="artikal.tip"
          name="tip-{{ i }}"
        >
          <option value="">(nije izabrano)</option>
          <option value="majica">Majica</option>
          <option value="haljina">Haljina</option>
          <option value="farmerice">Farmerice</option>
          <option value="jakna">Jakna</option>
          <option value="duks">Duks</option>
          <option value="suknja">Suknja</option>
          <option value="kaput">Kaput</option>
          <option value="kosulja">Košulja</option>
          <option value="sorts">Šorts</option>
          <option value="trenirka">Trenerka</option>
          <option value="bluza">Bluza</option>
        </select>

        <!-- Kategorija (muški / ženski / unisex) -->
        <label for="kategorija-{{ i }}">Kategorija:</label>
        <select
          id="kategorija-{{ i }}"
          [(ngModel)]="artikal.kategorija"
          name="kategorija-{{ i }}"
        >
          <option value="">(nije izabrano)</option>
          <option value="muski">Muški</option>
          <option value="zenski">Ženski</option>
          <option value="unisex">Unisex</option>
        </select>

        <!-- Boja -->
        <label for="boja-{{ i }}">Boja:</label>
        <select
          id="boja-{{ i }}"
          [(ngModel)]="artikal.boja"
          name="boja-{{ i }}"
        >
          <option value="">(nije izabrano)</option>
          <option value="bela">Bela</option>
          <option value="crna">Crna</option>
          <option value="roze">Roze</option>
          <option value="crvena">Crvena</option>
          <option value="plava">Plava</option>
          <option value="zelena">Zelena</option>
          <option value="žuta">Žuta</option>
          <option value="siva">Siva</option>
          <option value="narandžasta">Narandžasta</option>
          <option value="ljubičasta">Ljubičasta</option>
          <option value="braon">Braon</option>
        </select>

        <!-- Obavezna polja: veličina i cena -->
        <label for="velicina-{{ i }}">Veličina:</label>
        <select
          id="velicina-{{ i }}"
          [(ngModel)]="artikal.velicina"
          name="velicina-{{ i }}"
          (change)="validateField(artikal, i)"
        >
          <option value="">(izaberite veličinu)</option>
          <option value="XS">XS</option>
          <option value="S">S</option>
          <option value="M">M</option>
          <option value="L">L</option>
          <option value="XL">XL</option>
          <option value="XXL">XXL</option>
          <option value="XXXL">XXXL</option>
          <option value="Jedna veličina">Jedna veličina</option>
        </select>

        <label for="cena-{{ i }}">Cena:</label>
        <input
          type="number"
          id="cena-{{ i }}"
          [(ngModel)]="artikal.cena"
          name="cena-{{ i }}"
          placeholder="Unesite cenu u dinarima"
          (input)="validateField(artikal, i)"
        />

        <!-- Opcioni opis -->
        <label for="opis-{{ i }}">Opis (opciono):</label>
        <textarea
          id="opis-{{ i }}"
          [(ngModel)]="artikal.opis"
          name="opis-{{ i }}"
          placeholder="Dodajte opis artikla (materijal, stanje, brend...)"
        ></textarea>

        <!-- Jedna poruka o grešci po artiklu (za veličinu/cenu) -->
        <div *ngIf="errors[i]" class="error">
          {{ errors[i] }}
        </div>
      </div>
    </div>
  </div>

  <button (click)="onSubmit()" [disabled]="artikli.length === 0">
    Sačuvaj artikle
  </button>
</div>
